 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    bg = grid[0][1] if w > 1 else grid[0][0]
    markers = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
               if grid[r][c] not in (bg, 9)]
    # A sparse interior marker is the origin of a ray directed toward the
    # opposite side of its corresponding boundary rail.
    for r, c, color in markers:
        out[r][c] = 4
        if any(grid[y][0] != bg for y in range(h)):
            for x in range(c + 1, w):
                if grid[r][x] == bg:
                    out[r][x] = color
        elif any(grid[y][-1] != bg for y in range(h)):
            for x in range(c - 1, -1, -1):
                if grid[r][x] == bg:
                    out[r][x] = color
        elif any(grid[0][x] != bg for x in range(w)):
            for y in range(r + 1, h):
                if grid[y][c] == bg:
                    out[y][c] = color
        else:
            for y in range(r - 1, -1, -1):
                if grid[y][c] == bg:
                    out[y][c] = color
    return out
",
 "cross_profile": false
}

